/* Block Academy 22.10.0: offline, touch-first, progressive practice. */
(function(){'use strict';
const B=window.FMBlockModel,M=window.FMModel;
if(!B||!M)return;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DB_CARDS={
 'Least privilege':'Give a person only the permissions needed for an approved task and scope.',
 'Role-based access':'Authorize capabilities through approved roles rather than copying another person’s privileges.',
 'Access lifecycle':'Grant, periodically review, modify, and revoke access when duties change.',
 'Interface mapping':'Rules that move and translate source data into its destination system.',
 'Failed import':'A data transfer or transformation that must be diagnosed, corrected, and selectively replayed.',
 'Audit trail':'A verifiable history of who changed records or access, and why.',
 'Rollback':'Return a system to an approved known state after an unsafe or failed change.',
 'Recovery verification':'Re-run the original affected user task and check evidence that the service is restored.',
 'Separation of duties':'Split approval, execution, and verification where practical to prevent undetected misuse.',
 'Scope':'The unit, system, or records that a specific access authorization covers.'
};
let callbacks=null,animationToken=0,playingAnimation=false,ignoreClickUntil=0,drag=null;
function ensure(state){
 if(!state.academy||typeof state.academy!=='object')state.academy={};const a=state.academy;
 if(!a.progress||typeof a.progress!=='object')a.progress={};
 if(!B.MISSIONS.some(m=>m.id===a.mission))a.mission=1;
 if(!Number.isInteger(a.round)||a.round<1||a.round>90)a.round=Math.min(90,(a.progress[a.mission]||0)+1);
 if(!Number.isInteger(a.variation)||a.variation<0)a.variation=0;
 if(!['play','victory'].includes(a.stage))a.stage='play';
 if(!a.placements||typeof a.placements!=='object')a.placements=B.emptyPlacements(B.makeChallenge(a.mission,a.round,a.variation));
 return a;
}
function ensureCards(state){const f=state.flashcards||(state.flashcards={});if(!['scheduling','analysis','documentation','integrity','dbm'].includes(f.category))f.category='scheduling';if(!Number.isInteger(f.index)||f.index<0)f.index=0;if(!Number.isInteger(f.orderSeed)||f.orderSeed<0)f.orderSeed=0;return f}
function eCard(m){const [a,b]=m.color||B.color(0);return `style="--tile-a:${a};--tile-b:${b}"`}
function piece(m,context='tray',extra=''){const blocked=m.status&&m.status!=='FMC',isAircraft=!!m.status,title=m.title||m.id,detail=isAircraft?(m.status==='FMC'?`${m.daysIdle}d idle${m.phaseHours<=16?' · '+m.phaseHours+'h to Phase':''}`:m.status):m.detail;
 return `<button type="button" class="academy-piece ${isAircraft?'academy-aircraft':'academy-decision'} ${blocked?'academy-grounded':''} ${context==='slot'?'in-slot':''}" ${eCard(m)} data-academy-tile="${esc(m.id)}" aria-label="${esc((isAircraft?'Aircraft ':'Block ')+title+'; '+detail)}" ${extra}><strong class="academy-piece-id">${esc(title)}</strong><span class="academy-piece-sub">${esc(detail)}</span></button>`}
function statusLegend(){return `<div class="academy-legend"><span><i style="background:#16bc8c"></i>Available</span><span><i style="background:#ed6d7c"></i>NMC / down</span><span><i style="background:#ae86ed"></i>Phase priority</span><span>Touch or drag</span></div>`}
function mainHome(state){const a=ensure(state),total=B.MISSIONS.reduce((n,m)=>n+Math.min(90,Number(a.progress[m.id]||0)),0),next=B.MISSIONS.find(m=>(a.progress[m.id]||0)<90)||B.MISSIONS[0];
 return `<div class="academy-view academy-home"><section class="academy-hero"><div class="academy-kicker">MAINTENANCE MANAGEMENT · BLOCK ACADEMY</div><div class="academy-hero-plane" aria-hidden="true">✈</div><h1>REVENGE OF<br><em>THE NONNER</em></h1><p>Move the blocks. Solve the problem. Keep the mission flying.</p><button class="academy-cta" data-academy-mission="${next.id}">▶ PLAY NEXT MISSION · ${esc(next.title)}</button><div class="academy-footline">NO TIMER · works offline · touch or drag · progress saved</div></section><section class="academy-summary"><div><strong>${total}/630</strong><span>repetitions complete</span></div><div><strong>${B.MISSIONS.filter(m=>a.progress[m.id]>=90).length}/7</strong><span>missions completed</span></div></section><div class="academy-sectionhead"><div><small>THE SEVEN-MISSION CAMPAIGN</small><h2>Pick a puzzle</h2></div><button class="academy-outline" data-route="flashcards:home">▣ Flashcards</button></div><div class="academy-mission-list">${B.MISSIONS.map(m=>{const done=a.progress[m.id]||0,idx=m.id-1;return `<button class="academy-mission" data-academy-mission="${m.id}"><span class="academy-mission-icon" style="--tile-a:${B.color(idx*2)[0]};--tile-b:${B.color(idx*2)[1]}">${['✈','▦','◩','▤','⌁','✓','⚙'][idx]}</span><span class="academy-mission-details"><small>${m.id} · ${esc(m.discipline.toUpperCase())}</small><strong>${esc(m.title)}</strong><span>${esc(m.subtitle)}</span><span class="academy-progress-track"><i style="width:${Math.floor(done/90*100)}%"></i></span></span><span class="academy-count">${done}/90</span></button>`}).join('')}</div><section class="academy-deeper"><h2>Advanced simulators</h2><p>All existing skill trainers and the 90-day Scheduling Capstone remain available.</p><div class="academy-deeper-links">${[['scheduling','Scheduling'],['analysis','Analysis'],['doc','Documentation'],['integrity','Data Integrity'],['dbm','Database & Systems']].map(([k,v])=>`<button data-route="${k}:home">${esc(v)} →</button>`).join('')}</div></section></div>`}
function slotView(s,p,ch){const ids=p[s.id]||[],count=s.count||1;return `<section class="academy-blockbank"><header class="academy-blockbank-head"><h3>${esc(s.title)}</h3><span>${ids.filter(Boolean).length}/${count}</span></header><div class="academy-slots ${ch.kind==='launch'?'academy-wave-slots':'academy-task-slots'}">${Array.from({length:count},(_,i)=>{const id=ids[i],m=ch.kind==='launch'?ch.aircraft.find(x=>x.id===id):ch.pieces.find(x=>x.id===id);return `<div class="academy-slot ${m?'occupied':''}" data-academy-slot="${s.id}:${i}" role="button" tabindex="0" aria-label="${esc(s.title)}, slot ${i+1}, ${m?m.title||m.id:'empty'}">${m?piece(m,'slot')+`<button class="academy-slot-remove" data-academy-remove="${s.id}:${i}" aria-label="Remove ${esc(m.title||m.id)}">×</button>`:`<span class="academy-placeholder">${count===1?'DROP HERE':i+1}<small>＋</small></span>`}</div>`}).join('')}</div></section>`}
function runway(ch,p){const first=p.first||[];return `<div class="academy-runway" aria-label="Launch door and departing aircraft"><div class="academy-runway-label">DEPARTURE LANE · ONE AT A TIME</div><div class="academy-runway-stripes" aria-hidden="true"></div><div class="academy-door-frame" aria-hidden="true"><div class="academy-door-sign">FLIGHT LINE</div><div class="academy-doorway"><span>✈</span></div></div>${playingAnimation?first.map((id,i)=>{const m=ch.aircraft.find(x=>x.id===id);return `<div class="academy-taxi" style="--taxi-index:${i};--tile-a:${m.color[0]};--tile-b:${m.color[1]}"><strong>${esc(id)}</strong><span>✈</span></div>`}).join(''):`<div class="academy-waiting">${first.filter(Boolean).length} aircraft queued</div>`}</div>`}
function currentChallenge(a){return B.makeChallenge(a.mission,a.round,a.variation)}
function playView(state){const a=ensure(state),mission=B.MISSIONS.find(m=>m.id===a.mission),ch=currentChallenge(a),t=B.tier(a.round),completed=a.progress[a.mission]||0;
 if(a.stage==='victory')return `<div class="academy-view"><div class="academy-subnav"><button data-route="academy:home">⌂ Home</button><button data-route="flashcards:home">▣ Flashcards</button></div><section class="academy-result"><div class="academy-result-icon">✓</div><div class="academy-kicker">${esc(mission.discipline)} · ${esc(t.name)}</div><h1>MISSION COMPLETE</h1><p>${a.assisted?'Model demonstration complete. Repeat independently for completion credit.':`Repetition ${a.round} of 90 complete. Your progress has been saved.`}</p><div class="academy-summary"><strong>${completed}/90</strong> repetitions cleared</div><button class="academy-cta" data-academy-action="${a.assisted?'retry':'continue'}">${a.assisted?'↻ TRY INDEPENDENTLY':completed>=90?'▶ NEXT MISSION':'▶ NEXT REPETITION'}</button><button class="academy-outline" data-route="academy:home">Return to campaign</button></section></div>`;
 const items=ch.kind==='launch'?ch.aircraft:ch.pieces,placed=a.placements,selected=a.selectedPiece;
 return `<div class="academy-view academy-play"><div class="academy-subnav"><button data-route="academy:home">⌂ Home</button><span>MISSION ${mission.id} / 7 · ${esc(t.name)}</span><button data-route="flashcards:home">▣ Flashcards</button></div><section class="academy-titlepanel"><div class="academy-kicker">${esc(mission.discipline.toUpperCase())} · REPETITION ${a.round} OF 90</div><h1>${esc(mission.title)}</h1><p>${esc(ch.prompt)}</p><div class="academy-microprogress"><div><i style="width:${Math.floor(completed/90*100)}%"></i></div><span>${completed}/90 complete</span></div><p class="academy-requirement">${esc(ch.requirement||ch.detail||t.hint)}</p>${ch.kind==='launch'?`<div class="academy-prompt-count">${ch.needFirst} FIRST WAVE · ${ch.needTurn} TURNS${ch.spareRequired?' · 1 SPARE':''}</div>`:''}</section><section class="academy-board">${ch.slots.map(s=>slotView(s,placed,ch)).join('')}${ch.kind==='launch'?runway(ch,placed):''}<p class="academy-instruction">Drag a colored block into an empty slot, or tap the block and then tap a destination. Tap × to remove it.</p></section><section class="academy-bank"><header><h2>${ch.kind==='launch'?'AIRCRAFT BLOCKS':'DECISION BLOCKS'}</h2><span>${selected?`Selected: ${esc(selected)}`:'Touch or drag'}</span></header><div class="academy-tray">${items.map(m=>`<div class="academy-tray-cell ${selected===m.id?'chosen':''}">${piece(m,'tray',selected===m.id?'aria-pressed="true"':'aria-pressed="false"')}</div>`).join('')}</div>${ch.kind==='launch'?statusLegend():''}</section>${a.message?`<div class="academy-alert ${a.messageGood?'good':'bad'}" role="status">${a.messageGood?'✓':'!'} ${esc(a.message)}</div>`:''}<div class="academy-game-actions"><button class="academy-cta" data-academy-action="check" ${playingAnimation?'disabled':''}>${playingAnimation?'✈ AIRCRAFT DEPARTING…':ch.kind==='launch'?'✈ LAUNCH WAVE':'✓ CHECK DECISIONS'}</button><button class="academy-reset" data-academy-action="reset" title="Clear this round" aria-label="Reset this round">↻</button></div><div class="academy-assistance"><button data-academy-action="hint">Hint</button><button data-academy-action="model">Show model</button><button data-academy-action="variation">New variation</button></div>${a.hint?`<section class="academy-help"><strong>Hint</strong><p>${esc(ch.kind==='launch'?`Only FMC aircraft may fly. Every turn is part of the first wave. ${ch.requirement||''}${ch.limitNearPhase!==null?' Schedule at most one aircraft with 16 or fewer hours to Phase in the first wave.':''}`:ch.id===5?'The denominator must match the specific rate; never assume every rate uses flights.':ch.id===6?'Identify the mismatched field from the approved source. Preserve the original in an auditable correction.':ch.id===7?'Choose minimum role and scope; then verify the original user workflow.':'Read the approved instruction, establish applicability and resources, accomplish, then verify closeout.')}</p></section>`:''}<p class="academy-round-note">${esc(t.hint)} ${a.assisted?'Model assistance is active; reset this round to earn completion credit.':''}</p><div class="academy-mobile-rack" aria-label="Quick drag tray"><button class="academy-rack-scroll" data-academy-rackscroll="left" aria-label="Earlier blocks">‹</button><div class="academy-rack-items">${items.map(m=>piece(m,'rack')).join('')}</div><button class="academy-rack-scroll" data-academy-rackscroll="right" aria-label="More blocks">›</button></div></div>`}
function cardsFor(category){if(category==='scheduling')return Object.entries(M.SCHED_VOCAB).map(([term,meaning])=>({term,meaning}));if(category==='documentation')return Object.entries(M.DOC_TERMS).map(([term,meaning])=>({term,meaning}));if(category==='integrity')return Object.entries(M.INTEGRITY_FIELDS).map(([term,meaning])=>({term,meaning}));if(category==='analysis')return M.METRICS.map(m=>({term:m.name,meaning:`${m.meaning} Numerator: ${m.num}. Denominator: ${m.den}.` }));return Object.entries(DB_CARDS).map(([term,meaning])=>({term,meaning}))}
function orderedCards(f){const cards=cardsFor(f.category);if(!f.orderSeed)return cards;let x=1+f.orderSeed*17+f.category.length*29;for(let i=cards.length-1;i>0;i--){x=(x*1664525+1013904223)>>>0;const j=x%(i+1);[cards[i],cards[j]]=[cards[j],cards[i]]}return cards}
function flashcardsView(state){const f=ensureCards(state),cards=orderedCards(f),index=f.index%cards.length,c=cards[index];return `<div class="academy-view academy-flashcards"><div class="academy-subnav"><button data-route="academy:home">⌂ Home</button><span>STUDY TERMS</span><button data-route="scheduling:home">Advanced practice →</button></div><section class="academy-titlepanel"><div class="academy-kicker">OFFLINE FLASHCARDS · FIVE DISCIPLINES</div><h1>Learn the language</h1><p>Select a discipline. Tap the card to flip it and reveal the explanation.</p></section><div class="academy-flash-tabs">${[['scheduling','Scheduling'],['analysis','Analysis'],['documentation','Documentation'],['integrity','Data Integrity'],['dbm','Database & Systems']].map(([k,v])=>`<button class="${f.category===k?'active':''}" data-flash-category="${k}">${esc(v)}</button>`).join('')}</div><div class="academy-flash-count">${index+1} / ${cards.length} · ${esc(f.category.toUpperCase())}</div><button class="academy-flashcard ${f.flipped?'flipped':''}" data-flash-action="flip"><span class="academy-flash-side">${f.flipped?'DEFINITION':'TERM'}</span><strong>${esc(f.flipped?c.meaning:c.term)}</strong><span class="academy-flash-side">Tap to ${f.flipped?'see the term':'reveal the answer'}</span></button><div class="academy-flash-actions"><button data-flash-action="prev">← Previous</button><button data-flash-action="flip">Flip card</button><button data-flash-action="next">Next →</button><button data-flash-action="shuffle">Shuffle</button></div><div class="academy-flash-footer"><button class="academy-outline" data-route="academy:home">Back to Block Academy</button></div></div>`}
function newRound(a){a.stage='play';a.placements=B.emptyPlacements(currentChallenge(a));a.selectedPiece=null;a.message=null;a.messageGood=false;a.hint=false;a.assisted=false;playingAnimation=false;animationToken++}
function startMission(state,id,ui){const a=ensure(state);a.mission=id;a.round=Math.min(90,Math.max(1,(a.progress[id]||0)+1));a.variation=0;newRound(a);ui.setRoute('academy','play')}
function placeAt(state,id,slot,index,ui){const a=ensure(state);if(a.stage!=='play'||playingAnimation)return;const ch=currentChallenge(a),r=B.place(ch,a.placements,id,slot,index);if(r.ok){a.placements=r.placements;a.message=null;a.selectedPiece=null;a.hint=false;ui.save();ui.render()}else{a.message=r.message;a.messageGood=false;ui.save();ui.render()}}
function launch(state,ui){const a=ensure(state);if(playingAnimation)return;const ch=currentChallenge(a),result=B.validate(ch,a.placements);if(!result.ok){a.message=result.message;a.messageGood=false;ui.tone(false);ui.save();ui.render();return}
 a.message=result.message;a.messageGood=true;const mission=a.mission,round=a.round,variation=a.variation;
 if(!a.assisted&&round===Math.min(90,(a.progress[mission]||0)+1))a.progress[mission]=Math.min(90,round);
 ui.tone(true);ui.save();
 playingAnimation=ch.kind==='launch';const token=++animationToken;ui.render();
 if(ch.kind!=='launch'){a.stage='victory';ui.save();ui.render();return}
 window.setTimeout(()=>{if(token!==animationToken)return;playingAnimation=false;if(a.mission===mission&&a.round===round&&a.variation===variation){a.stage='victory';ui.save();if(state.module==='academy')ui.render()}},1650+(ch.needFirst-1)*365+250);
}
function handleClick(dataset,state,ui){if(dataset.academyRackscroll){const rack=document.querySelector?.('.academy-rack-items');rack?.scrollBy?.({left:dataset.academyRackscroll==='left'?-240:240,behavior:'smooth'});return true}if(dataset.academyMission){const id=Number(dataset.academyMission);if(B.MISSIONS.some(m=>m.id===id))startMission(state,id,ui);return true}
 if(dataset.academyAction){const a=ensure(state);switch(dataset.academyAction){
 case 'check':launch(state,ui);break;
 case 'reset':newRound(a);ui.save();ui.render();break;
 case 'variation':a.variation++;newRound(a);ui.save();ui.render();break;
 case 'hint':a.hint=!a.hint;ui.save();ui.render();break;
 case 'model':a.placements=B.modelPlacements(currentChallenge(a));a.assisted=true;a.message='Model shown. Practice it, then reset to complete independently.';a.messageGood=true;ui.save();ui.render();break;
 case 'retry':newRound(a);ui.save();ui.render();break;
 case 'continue':if(a.round>=90){const m=B.MISSIONS.find(x=>(a.progress[x.id]||0)<90);if(m){startMission(state,m.id,ui)}else{ui.setRoute('academy','home')}break}a.round++;a.variation=0;newRound(a);ui.save();ui.render();break;
 }return true}
 if(dataset.academyRemove){const a=ensure(state);if(a.stage==='play'&&!playingAnimation){const [s,i]=dataset.academyRemove.split(':');a.placements=B.remove(a.placements,s,Number(i));a.selectedPiece=null;a.message=null;ui.save();ui.render()}return true}
 if(dataset.academyTile){if(Date.now()<ignoreClickUntil)return true;const a=ensure(state);if(a.stage!=='play'||playingAnimation)return true;const id=dataset.academyTile;a.selectedPiece=a.selectedPiece===id?null:id;a.message=null;ui.save();ui.render();return true}
 if(dataset.academySlot){const a=ensure(state);if(a.selectedPiece){const [s,i]=dataset.academySlot.split(':');placeAt(state,a.selectedPiece,s,Number(i),ui)}return true}
 if(dataset.flashCategory){const f=ensureCards(state);f.category=dataset.flashCategory;f.index=0;f.flipped=false;f.orderSeed=0;ui.save();ui.render();return true}
 if(dataset.flashAction){const f=ensureCards(state),total=cardsFor(f.category).length;switch(dataset.flashAction){case 'flip':f.flipped=!f.flipped;break;case 'next':f.index=(f.index+1)%total;f.flipped=false;break;case 'prev':f.index=(f.index+total-1)%total;f.flipped=false;break;case 'shuffle':f.orderSeed++;f.index=0;f.flipped=false;break}ui.save();ui.render();return true}
 return false}
function attach(root,ui){callbacks=ui;
 root.addEventListener('pointerdown',e=>{if(ui.state().module!=='academy'||ui.state().screen!=='play'||playingAnimation)return;const tile=e.target.closest?.('[data-academy-tile]');if(!tile)return;drag={id:tile.dataset.academyTile,x:e.clientX,y:e.clientY,moved:false,ghost:null};try{tile.setPointerCapture(e.pointerId)}catch{}});
 root.addEventListener('pointermove',e=>{if(!drag)return;const distance=Math.hypot(e.clientX-drag.x,e.clientY-drag.y);if(distance<9&&!drag.moved)return;if(!drag.moved){drag.moved=true;const copy=e.target.closest?.('[data-academy-tile]');if(copy&&document.body){drag.ghost=copy.cloneNode(true);drag.ghost.classList.add('academy-ghost');drag.ghost.removeAttribute('data-academy-tile');document.body.appendChild(drag.ghost)}}if(drag.ghost){drag.ghost.style.left=e.clientX+'px';drag.ghost.style.top=e.clientY+'px'}if(e.cancelable)e.preventDefault()});
 root.addEventListener('pointerup',e=>{if(!drag)return;const d=drag;drag=null;if(d.ghost)d.ghost.remove();if(!d.moved)return;ignoreClickUntil=Date.now()+500;const target=document.elementFromPoint?.(e.clientX,e.clientY);const slot=target?.closest?.('[data-academy-slot]');if(slot){const [s,i]=slot.dataset.academySlot.split(':');placeAt(ui.state(),d.id,s,Number(i),ui)}else{const a=ensure(ui.state());a.selectedPiece=d.id;ui.save();ui.render()}});
 root.addEventListener('pointercancel',()=>{if(drag?.ghost)drag.ghost.remove();drag=null});
 root.addEventListener('keydown',e=>{if(ui.state().module!=='academy'||(e.key!=='Enter'&&e.key!==' '))return;const slot=e.target.closest?.('[data-academy-slot]');if(slot&&e.target===slot){e.preventDefault();const a=ensure(ui.state());if(a.selectedPiece){const [s,i]=slot.dataset.academySlot.split(':');placeAt(ui.state(),a.selectedPiece,s,Number(i),ui)}}});
}
window.FMBlockAcademy={renderAcademy:state=>state.screen==='play'?playView(state):mainHome(state),renderFlashcards:flashcardsView,handleClick,attach,ensure,model:B};
})();
